\small
\caption{QwQ-32B per-benchmark breakdown (48 questions).}
\label{tab:qwq}
\begin{tabular}{lccc}
\toprule
\textbf{Benchmark} & $n$ & $C_0$ & Gap \\
\midrule
AIME & 22 & 0.0\% & 0.0 \\
FOLIO & 10 & 0.0\% & 0.0 \\
ProofWriter & 16 & 18.75\% & 0.0 \\
\midrule
